import pytest
import requests

# Step 1: Analysis
# Endpoint: /v2/pet
# Method: PUT
# Security: OAuth2 (petstore_auth)
# Responses: 400, 404, 405

# Step 2: Test Structure Planning
@pytest.mark.parametrize("status_code, description", [
    (400, "Invalid ID supplied"),
    (404, "Pet not found"),
    (405, "Validation exception")
])
def test_update_pet_invalid_cases(api_client, oauth2_token, status_code, description):
    """Test update pet with invalid scenarios."""
    headers = {"Authorization": f"Bearer {oauth2_token}", "Content-Type": "application/json"}
    invalid_pet_data = {
        "id": -1,  # Invalid ID
        "name": "InvalidPet",
        "photoUrls": ["http://example.com/photo1.jpg"],
        "status": "available"
    }
    response = api_client.make_request("v2/pet", method='PUT', headers=headers, params=None, json=invalid_pet_data)
    assert response.status_code == status_code
    assert description in response.text

def test_update_pet_valid(api_client, oauth2_token):
    """Test update pet with valid data."""
    headers = {"Authorization": f"Bearer {oauth2_token}", "Content-Type": "application/json"}
    valid_pet_data = {
        "id": 1,
        "name": "UpdatedPet",
        "photoUrls": ["http://example.com/photo1.jpg"],
        "status": "available"
    }
    response = api_client.make_request("v2/pet", method='PUT', headers=headers, params=None, json=valid_pet_data)
    assert response.status_code == 200
    assert response.json().get("name") == "UpdatedPet"

def test_update_pet_missing_auth(api_client):
    """Test update pet without authentication."""
    headers = {"Content-Type": "application/json"}
    pet_data = {
        "id": 1,
        "name": "PetWithoutAuth",
        "photoUrls": ["http://example.com/photo1.jpg"],
        "status": "available"
    }
    response = api_client.make_request("v2/pet", method='PUT', headers=headers, params=None, json=pet_data)
    assert response.status_code == 401  # Assuming 401 for missing auth

